steps:
Write the contract first, in tests/frete.test.ts (amounts in cents):
import { describe, expect, it } from 'vitest';
import { frete } from '../src/frete';

describe('delivery fee (contract)', () => {
  it('R$ 99.99 pays R$ 8', () => expect(frete(9999)).toBe(800));
  it('exactly R$ 100.00 still pays', () => expect(frete(10000)).toBe(800));
  it('above R$ 100 is free', () => expect(frete(10001)).toBe(0));
});

